package com.fream.back.domain.m16.service.command;

import com.fream.back.domain.m16.entity.Xtz73Status;
import com.fream.back.domain.m16.entity.Xdg64;
import com.fream.back.domain.m16.entity.Xzj27;
import com.fream.back.domain.m16.exception.*;
import com.fream.back.domain.m16.repository.Xzj27Repository;
import com.fream.back.domain.m06.dto.Xbf54RequestDto;
import com.fream.back.domain.m02.entity.Xdh20;
import com.fream.back.domain.m02.service.p14.Xdh20QueryService;
import com.fream.back.domain.m10.entity.Xgg74;
import com.fream.back.domain.m10.entity.Xzz58;
import com.fream.back.domain.m10.service.query.Xzz58QueryService;
import com.fream.back.domain.m13.entity.Xrd81;
import com.fream.back.domain.m13.service.query.Xrd81QueryService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;




@Service
@RequiredArgsConstructor
@Slf4j
public class Xzj27CommandService {

    private final Xzj27Repository orderBidRepository;
    private final Xdg64CommandService orderCommandService;
    private final Xdh20QueryService productSizeQueryService;
    private final Xrd81QueryService userQueryService;
    private final Xzz58QueryService saleBidQueryService;












    @Transactional
    public Xzj27 createOrderBid(String email, Long productSizeId, int bidPrice) {
        try {

            validateCreateOrderBidInput(email, productSizeId, bidPrice);


            Xrd81 user = userQueryService.findByEmail(email);


            Xdh20 productSize = productSizeQueryService.findById(productSizeId)
                    .orElseThrow(() -> new Xrf10Exception("해당 사이즈를 찾을 수 없습니다(ID: " + productSizeId + ")"));


            Xdg64 order = orderCommandService.createOrderFromBid(user, productSize, bidPrice);


            Xzj27 orderBid = createAndSaveOrderBid(user, productSize, bidPrice, order);

            return orderBid;
        } catch (Exception e) {
            handleOrderBidCreationException(e, "주문 입찰 생성");
            return null;
        }
    }




    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
        if (email == null || email.trim().isEmpty()) {
            throw new Xxd47Exception("사용자 이메일이 없습니다.");
        }
        if (productSizeId == null) {
            throw new Xrf10Exception("상품 사이즈 ID가 없습니다.");
        }
        if (bidPrice <= 0) {
            throw new Xwh31Exception("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
        }
    }




    private Xzj27 createAndSaveOrderBid(Xrd81 user, Xdh20 productSize, int bidPrice, Xdg64 order) {
        Xzj27 orderBid = Xzj27.builder()
                .user(user)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(Xtz73Status.PENDING)
                .order(order)
                .build();


        orderBid.assignOrder(order);

        return orderBidRepository.save(orderBid);
    }














    @Transactional
    public Xzj27 createInstantOrderBid(String buyerEmail, Long saleBidId, Long addressId,
                                          boolean isWarehouseStorage, Xbf54RequestDto paymentRequest) {
        try {

            validateInstantOrderBidInput(buyerEmail, saleBidId, addressId, paymentRequest);


            Xrd81 buyer = userQueryService.findByEmail(buyerEmail);


            Xzz58 saleBid = getSaleBidAndValidate(saleBidId);
            Xgg74 sale = saleBid.getSale();


            Xdg64 order = orderCommandService.createInstantOrder(
                    buyer,
                    saleBid,
                    addressId,
                    isWarehouseStorage,
                    paymentRequest
            );


            Xzj27 orderBid = createInstantOrderBid(order, saleBid, sale);

            return orderBid;
        } catch (Exception e) {
            handleOrderBidCreationException(e, "즉시 구매 주문 입찰 생성");
            return null;
        }
    }




    private void validateInstantOrderBidInput(String buyerEmail, Long saleBidId, Long addressId, Xbf54RequestDto paymentRequest) {
        if (buyerEmail == null || buyerEmail.trim().isEmpty()) {
            throw new Xxd47Exception("구매자 이메일이 없습니다.");
        }
        if (saleBidId == null) {
            throw new Xkt44Exception("판매 입찰 ID가 없습니다.");
        }
        if (addressId == null) {
            throw new Xnb95Exception("배송지 ID가 없습니다.");
        }
        if (paymentRequest == null) {
            throw new Xtj87Exception("결제 정보가 없습니다.");
        }
    }




    private Xzz58 getSaleBidAndValidate(Long saleBidId) {
        Xzz58 saleBid = saleBidQueryService.findById(saleBidId);
        if (saleBid == null) {
            throw new Xkt44Exception("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
        }

        Xgg74 sale = saleBid.getSale();
        if (sale == null) {
            throw new Xnb95Exception("판매 입찰과 연결된 판매 정보가 없습니다.");
        }

        return saleBid;
    }




    private Xzj27 createInstantOrderBid(Xdg64 order, Xzz58 saleBid, Xgg74 sale) {
        Xdh20 productSize = saleBid.getProductSize();

        Xzj27 orderBid = Xzj27.builder()
                .user(order.getUser())
                .productSize(productSize)
                .bidPrice(saleBid.getBidPrice())
                .status(Xtz73Status.MATCHED)
                .order(order)
                .sale(sale)
                .build();


        orderBid.assignOrder(order);


        orderBid.markAsInstantPurchase();
        return orderBidRepository.save(orderBid);
    }




    private void handleOrderBidCreationException(Exception e, String operation) {
        if (e instanceof Xdg64Exception) {
            throw (Xdg64Exception) e;
        }
        log.error("{} 중 오류 발생: {}", operation, e.getMessage(), e);
        throw new Xst47Exception(operation + " 중 오류가 발생했습니다: " + e.getMessage(), e);
    }








    @Transactional
    public void matchOrderBid(Xzj27 orderBid) {
        try {
            if (orderBid == null) {
                throw new Xvt58Exception("주문 입찰 정보가 없습니다.");
            }

            if (orderBid.getStatus() == Xtz73Status.MATCHED) {
                throw new Xmd85Exception("이미 매칭된 주문 입찰입니다(ID: " + orderBid.getId() + ")");
            }

            orderBid.updateStatus(Xtz73Status.MATCHED);
        } catch (Exception e) {
            if (e instanceof Xdg64Exception) {
                throw e;
            }
            log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
            throw new Xhz43Exception("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }









    @Transactional
    public void deleteOrderBid(Long orderBidId) {
        try {

            Xzj27 orderBid = orderBidRepository.findById(orderBidId)
                    .orElseThrow(() -> new Xvt58Exception("해당 주문 입찰을 찾을 수 없습니다(ID: " + orderBidId + ")"));


            if (orderBid.getSale() != null) {
                throw new Xmd85Exception("주문 입찰이 판매와 연결되어 있어 삭제할 수 없습니다.");
            }


            if (orderBid.getStatus() == Xtz73Status.MATCHED) {
                throw new Xmd85Exception("이미 매칭된 주문 입찰은 삭제할 수 없습니다.");
            }


            if (orderBid.getOrder() != null) {
                orderCommandService.deleteOrder(orderBid.getOrder().getId());
            }


            orderBidRepository.delete(orderBid);
        } catch (Exception e) {
            if (e instanceof Xdg64Exception) {
                throw e;
            }
            log.error("주문 입찰 삭제 중 오류 발생: {}", e.getMessage(), e);
            throw new Xdw92Exception("주문 입찰 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }
}package com.fream.back.domain.m16.entity;

