        }


        this.order = order;


        if (order != null) {
            this.status = Xtz73Status.MATCHED;


            if (order.getOrderBid() != this) {
                order.assignOrderBid(this);
            }
        }
    }






    public void assignSale(Xgg74 sale) {
        this.sale = sale;
        this.status = Xtz73Status.MATCHED;
